{"filePath": "Assets\Scripts\Source\LuckyHubEpisodeManager.cs", "content": "using System;
using System.Collections.Generic;
using Hazel;

namespace LuckyInterview
{
    /// <summary>
    /// Episode manager for Lucky Hub - handles observations, actions, rewards, and episode boundaries
    /// </summary>
    public class LuckyHubEpisodeManager : Entity
    {
        [Group("Scene References")]
        public Entity? taskController = null; // Reference to Take_ServerPlugger

        [Group("Scene References")]
        public Entity? armLeft = null;

        [Group("Scene References")]
        public Entity? armRight = null;

        [Group("Scene References")]
        public Entity? cable = null;

        [Group("Scene References")]
        public Entity? targetPort = null;

        [Group("Observation Cameras")]
        public Entity? overviewCamera = null;

        [Group("Observation Cameras")]
        public Entity? taskCamera = null;

        [Group("Episode Settings")]
        public float maxEpisodeTime = 120.0f;

        [Group("Episode Settings")]
        public float successDistance = 0.05f; // 5cm tolerance for successful insertion

        [Group("Episode Settings")]
        public bool autoReset = true;

        [Group("Reward Settings")]
        public float successReward = 100.0f;

        [Group("Reward Settings")]
        public float timeoutPenalty = -10.0f;

        [Group("Reward Settings")]
        public float progressRewardScale = 1.0f;

        [Group("Reward Settings")]
        public float collisionPenalty = -5.0f;

        // Episode state
        private bool _episodeActive = false;
        private float _episodeStartTime = 0f;
        private float _lastReward = 0f;
        private float _cumulativeReward = 0f;
        private int _episodeCount = 0;

        // Initial positions for reset
        private Transform _initialCableTransform;
        private Dictionary<Entity, Transform> _initialTransforms = new();

        // Task progress tracking
        private Vector3 _cableStartPosition;
        private Vector3 _targetPosition;
        private float _initialDistance;
        private float _bestDistance = float.MaxValue;

        protected override void OnCreate()
        {
            Log.Info("LuckyHub Episode Manager initialized");

            if (!ValidateReferences())
            {
                Log.Error("Missing required references in LuckyHubEpisodeManager");
                return;
            }

            StoreInitialTransforms();
            InitializeEpisode();
        }

        protected override void OnUpdate()
        {
            if (!_episodeActive) return;

            float elapsedTime = Time.Time - _episodeStartTime;

            // Check for episode termination conditions
            if (elapsedTime > maxEpisodeTime)
            {
                EndEpisode(EpisodeResult.Timeout);
                return;
            }

            if (CheckTaskSuccess())
            {
                EndEpisode(EpisodeResult.Success);
                return;
            }

            // Calculate and apply continuous rewards
            CalculateStepReward();
        }

        /// <summary>
        /// Initialize a new episode
        /// </summary>
        [Button("Start Episode")]
        public void InitializeEpisode()
        {
            Log.Info($"Starting episode {_episodeCount + 1}");

            _episodeActive = true;
            _episodeStartTime = Time.Time;
            _cumulativeReward = 0f;
            _bestDistance = float.MaxValue;
            _episodeCount++;

            // Reset scene to initial state
            ResetScene();

            // Initialize task tracking
            if (cable != null && targetPort != null)
            {
                _cableStartPosition = cable.Transform.WorldTransform.Position;
                _targetPosition = targetPort.Transform.WorldTransform.Position;
                _initialDistance = Vector3.Distance(_cableStartPosition, _targetPosition);
            }

            // Start the task
            var controller = taskController?.As<Take_ServerPlugger>();
            controller?.StartEpisode();
        }

        /// <summary>
        /// End the current episode
        /// </summary>
        public void EndEpisode(EpisodeResult result)
        {
            _episodeActive = false;
            float episodeDuration = Time.Time - _episodeStartTime;

            // Apply final reward
            switch (result)
            {
                case EpisodeResult.Success:
                    _cumulativeReward += successReward;
                    Log.Info($"Episode {_episodeCount} SUCCESS! Duration: {episodeDuration:F2}s, Total Reward: {_cumulativeReward:F2}");
                    break;

                case EpisodeResult.Timeout:
                    _cumulativeReward += timeoutPenalty;
                    Log.Warn($"Episode {_episodeCount} TIMEOUT after {episodeDuration:F2}s, Total Reward: {_cumulativeReward:F2}");
                    break;

                case EpisodeResult.Failure:
                    Log.Warn($"Episode {_episodeCount} FAILED after {episodeDuration:F2}s, Total Reward: {_cumulativeReward:F2}");
                    break;
            }

            // Log episode statistics for Lucky Hub
            LogEpisodeData(result, episodeDuration);

            if (autoReset)
            {
                this.Invoke(() => InitializeEpisode(), 2.0f);
            }
        }

        /// <summary>
        /// Reset scene to initial state
        /// </summary>
        [Button("Reset Scene")]
        public void ResetScene()
        {
            Log.Info("Resetting scene to initial state");

            // Reset cable position
            if (cable != null)
            {
                cable.Transform.WorldTransform = _initialCableTransform;
            }

            // Reset other entity positions
            foreach (var kvp in _initialTransforms)
            {
                if (kvp.Key != null)
                {
                    kvp.Key.Transform.WorldTransform = kvp.Value;
                }
            }

            // Reset robot arms to home positions
            var armLController = armLeft?.As<Panda_Arm_ServerController>();
            var armRController = armRight?.As<Panda_Arm_ServerController>();

            armLController?.ResetToHome();
            armRController?.ResetToHome();
            armLController?.EnqueueOpenGripper(0.1f);
            armRController?.EnqueueOpenGripper(0.1f);
        }

        /// <summary>
        /// Get current observations for the AI model
        /// </summary>
        public ObservationData GetObservations()
        {
            var obs = new ObservationData();

            // Robot joint states
            if (armLeft != null && armRight != null)
            {
                var leftController = armLeft.As<Panda_Arm_ServerController>();
                var rightController = armRight.As<Panda_Arm_ServerController>();

                obs.LeftArmJointPositions = leftController?.GetJointPositions() ?? new float[7];
                obs.RightArmJointPositions = rightController?.GetJointPositions() ?? new float[7];
                obs.LeftGripperState = leftController?.GetGripperState() ?? 0f;
                obs.RightGripperState = rightController?.GetGripperState() ?? 0f;
            }

            // Object positions
            if (cable != null)
            {
                obs.CablePosition = cable.Transform.WorldTransform.Position;
                obs.CableRotation = cable.Transform.WorldTransform.Rotation;
            }

            if (targetPort != null)
            {
                obs.TargetPosition = targetPort.Transform.WorldTransform.Position;
                obs.TargetRotation = targetPort.Transform.WorldTransform.Rotation;
            }

            // Task progress
            obs.DistanceToTarget = cable != null && targetPort != null ? 
                Vector3.Distance(cable.Transform.WorldTransform.Position, targetPort.Transform.WorldTransform.Position) : 0f;

            obs.EpisodeTime = Time.Time - _episodeStartTime;
            obs.IsEpisodeActive = _episodeActive;

            return obs;
        }

        /// <summary>
        /// Apply actions from the AI model
        /// </summary>
        public void ApplyActions(ActionData actions)
        {
            if (!_episodeActive) return;

            var leftController = armLeft?.As<Panda_Arm_ServerController>();
            var rightController = armRight?.As<Panda_Arm_ServerController>();

            // Apply joint velocities or positions
            leftController?.SetJointTargets(actions.LeftArmActions);
            rightController?.SetJointTargets(actions.RightArmActions);

            // Apply gripper commands
            if (actions.LeftGripperAction > 0.5f)
                leftController?.EnqueueCloseGripper(0.1f);
            else if (actions.LeftGripperAction < -0.5f)
                leftController?.EnqueueOpenGripper(0.1f);

            if (actions.RightGripperAction > 0.5f)
                rightController?.EnqueueCloseGripper(0.1f);
            else if (actions.RightGripperAction < -0.5f)
                rightController?.EnqueueOpenGripper(0.1f);
        }

        private bool ValidateReferences()
        {
            return taskController != null && 
                   armLeft != null && 
                   armRight != null && 
                   cable != null && 
                   targetPort != null;
        }

        private void StoreInitialTransforms()
        {
            if (cable != null)
            {
                _initialCableTransform = cable.Transform.WorldTransform;
            }

            _initialTransforms.Clear();
            if (armLeft != null) _initialTransforms[armLeft] = armLeft.Transform.WorldTransform;
            if (armRight != null) _initialTransforms[armRight] = armRight.Transform.WorldTransform;
        }

        private bool CheckTaskSuccess()
        {
            if (cable == null || targetPort == null) return false;

            float distance = Vector3.Distance(
                cable.Transform.WorldTransform.Position, 
                targetPort.Transform.WorldTransform.Position
            );

            return distance < successDistance;
        }

        private void CalculateStepReward()
        {
            if (cable == null || targetPort == null) return;

            float currentDistance = Vector3.Distance(
                cable.Transform.WorldTransform.Position, 
                targetPort.Transform.WorldTransform.Position
            );

            // Progress reward - reward for getting closer to target
            if (currentDistance < _bestDistance)
            {
                float progressReward = (_bestDistance - currentDistance) * progressRewardScale;
                _cumulativeReward += progressReward;
                _bestDistance = currentDistance;
            }

            // Small time penalty to encourage efficiency
            _cumulativeReward -= 0.01f;
        }

        private void LogEpisodeData(EpisodeResult result, float duration)
        {
            // This data structure can be logged to files for Lucky Hub training
            var episodeData = new EpisodeLogData
            {
                EpisodeNumber = _episodeCount,
                Result = result,
                Duration = duration,
                FinalReward = _cumulativeReward,
                FinalDistance = cable != null && targetPort != null ? 
                    Vector3.Distance(cable.Transform.WorldTransform.Position, targetPort.Transform.WorldTransform.Position) : 0f,
                Timestamp = DateTime.Now
            };

            // Log to console (Lucky Hub can capture this)
            Log.Info($"EPISODE_DATA: {episodeData.ToJson()}");
        }

        public enum EpisodeResult
        {
            Success,
            Failure,
            Timeout
        }
    }

    /// <summary>
    /// Observation data structure for AI model
    /// </summary>
    public struct ObservationData
    {
        public float[] LeftArmJointPositions;
        public float[] RightArmJointPositions;
        public float LeftGripperState;
        public float RightGripperState;
        public Vector3 CablePosition;
        public Vector3 CableRotation;
        public Vector3 TargetPosition;
        public Vector3 TargetRotation;
        public float DistanceToTarget;
        public float EpisodeTime;
        public bool IsEpisodeActive;
    }

    /// <summary>
    /// Action data structure from AI model
    /// </summary>
    public struct ActionData
    {
        public float[] LeftArmActions;  // Joint targets or velocities
        public float[] RightArmActions; // Joint targets or velocities
        public float LeftGripperAction; // -1 = open, +1 = close, 0 = hold
        public float RightGripperAction; // -1 = open, +1 = close, 0 = hold
    }

    /// <summary>
    /// Episode logging data for Lucky Hub
    /// </summary>
    public struct EpisodeLogData
    {
        public int EpisodeNumber;
        public LuckyHubEpisodeManager.EpisodeResult Result;
        public float Duration;
        public float FinalReward;
        public float FinalDistance;
        public DateTime Timestamp;

        public string ToJson()
        {
            return $"{{\"episode\":{EpisodeNumber},\"result\":\"{Result}\",\"duration\":{Duration:F2},\"reward\":{FinalReward:F2},\"distance\":{FinalDistance:F4},\"timestamp\":\"{Timestamp:yyyy-MM-dd HH:mm:ss}\"}}";
        }
    }
}"}

