using System.IO;
using Hazel;

namespace LuckyInterview
{
    /// <summary>
    /// Video recording system for capturing robot demonstrations
    /// </summary>
    public class VideoRecorder : Entity
    {
        [Group("Recording Settings")]
        public string outputDirectory = "Recordings";

        [Group("Recording Settings")]
        public string videoFileName = "DualPandaDemo";

        [Group("Recording Settings")]
        public float recordingDuration = 60.0f; // seconds

        [Group("Recording Settings")]
        public int frameRate = 30;

        [Group("Recording Settings")]
        public bool recordOnStart = false;

        [Group("Camera Settings")]
        public Entity? recordingCamera = null;

        [Group("Task Integration")]
        public Entity? episodeManager = null;

        [Group("Task Integration")]
        public bool recordEpisodes = true;

        // Recording state
        private bool _isRecording = false;
        private float _recordingStartTime = 0f;
        private float _recordingElapsedTime = 0f;
        private int _recordingCount = 0;
        private string _currentRecordingPath = "";

        protected override void OnCreate()
        {
            Log.Info("Video Recorder initialized");

            // Create output directory if it doesn't exist
            CreateOutputDirectory();

            if (recordOnStart)
            {
                StartRecording();
            }

            // Listen for episode events if episode manager is connected
            if (episodeManager != null && recordEpisodes)
            {
                Log.Info("Connected to episode manager for automatic recording");
            }
        }

        protected override void OnUpdate(float deltaTime)
        {
            if (_isRecording)
            {
                _recordingElapsedTime += deltaTime;

                // Check if recording duration exceeded
                if (_recordingElapsedTime >= recordingDuration)
                {
                    StopRecording();
                }

                // Update recording progress
                UpdateRecordingProgress();
            }
        }

        /// <summary>
        /// Start video recording
        /// </summary>
        [Button("Start Recording")]
        public void StartRecording()
        {
            if (_isRecording)
            {
                Log.Warn("Recording already in progress");
                return;
            }

            _recordingCount++;
            string timestamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
            string fileName = $"{videoFileName}_{timestamp}_{_recordingCount:D3}";
            _currentRecordingPath = Path.Combine(outputDirectory, fileName);

            _isRecording = true;
            _recordingElapsedTime = 0f;
            _recordingStartTime = 0f;

            Log.Info($"Started recording: {_currentRecordingPath}");
            Log.Info($"Recording duration: {recordingDuration}s at {frameRate}fps");

            // Here you would typically interface with the engine's built-in recording
            // For now, we'll simulate the recording process and log frame captures
            SimulateRecordingStart();
        }

        /// <summary>
        /// Stop video recording
        /// </summary>
        [Button("Stop Recording")]
        public void StopRecording()
        {
            if (!_isRecording)
            {
                Log.Warn("No recording in progress");
                return;
            }

            _isRecording = false;

            Log.Info($"Recording stopped. Duration: {_recordingElapsedTime:F2}s");
            Log.Info($"Saved to: {_currentRecordingPath}");

            // Finalize the recording
            SimulateRecordingStop();
        }

        /// <summary>
        /// Record a single episode
        /// </summary>
        [Button("Record Episode")]
        public void RecordEpisode()
        {
            if (episodeManager == null)
            {
                Log.Error("Episode manager not assigned");
                return;
            }

            Log.Info("Starting episode recording...");

            // Start recording
            StartRecording();

            // Trigger episode start
            var manager = episodeManager.As<LuckyHubEpisodeManager>();
            if (manager != null)
            {
                manager.InitializeEpisode();
                Log.Info("Episode started with recording");
            }
        }

        /// <summary>
        /// Record multiple episodes in sequence
        /// </summary>
        [Button("Record Multiple Episodes")]
        public void RecordMultipleEpisodes()
        {
            // This would typically be implemented with a coroutine or state machine
            Log.Info("Multiple episode recording not yet implemented");
            Log.Info("Use 'Record Episode' button for individual episodes");
        }

        /// <summary>
        /// Set recording camera
        /// </summary>
        public void SetRecordingCamera(Entity camera)
        {
            recordingCamera = camera;
            Log.Info($"Recording camera set to: {camera?.Tag ?? "null"}");
        }

        /// <summary>
        /// Get recording status
        /// </summary>
        public (bool isRecording, float elapsedTime, float remainingTime, string currentPath) GetRecordingStatus()
        {
            float remainingTime = _isRecording ? Math.Max(0, recordingDuration - _recordingElapsedTime) : 0f;
            return (_isRecording, _recordingElapsedTime, remainingTime, _currentRecordingPath);
        }

        private void CreateOutputDirectory()
        {
            try
            {
                if (!Directory.Exists(outputDirectory))
                {
                    Directory.CreateDirectory(outputDirectory);
                    Log.Info($"Created output directory: {outputDirectory}");
                }
            }
            catch (Exception e)
            {
                Log.Error($"Failed to create output directory: {e.Message}");
            }
        }

        private void SimulateRecordingStart()
        {
            // In a real implementation, this would:
            // 1. Set up frame capture from the specified camera
            // 2. Initialize video encoder (H.264, etc.)
            // 3. Start capturing frames at specified frame rate

            Log.Info("=== RECORDING SIMULATION ===");
            Log.Info("In a real implementation, this would:");
            Log.Info("1. Capture frames from the recording camera");
            Log.Info("2. Encode to video file (MP4/AVI)");
            Log.Info("3. Save to the specified path");
            Log.Info("===========================");
        }

        private void SimulateRecordingStop()
        {
            // In a real implementation, this would:
            // 1. Stop frame capture
            // 2. Finalize video file
            // 3. Save metadata/timestamps

            Log.Info("Recording finalized and saved");

            // Log recording statistics
            LogRecordingStats();
        }

        private void UpdateRecordingProgress()
        {
            // Log progress every 10 seconds
            if (MathF.Floor(_recordingElapsedTime / 10f) > MathF.Floor((_recordingElapsedTime - Time.DeltaTime) / 10f))
            {
                float progress = (_recordingElapsedTime / recordingDuration) * 100f;
                Log.Info($"Recording progress: {progress:F1}% ({_recordingElapsedTime:F1}s / {recordingDuration:F1}s)");
            }
        }

        private void LogRecordingStats()
        {
            int totalFrames = (int)(_recordingElapsedTime * frameRate);
            long estimatedFileSize = totalFrames * 50000; // Rough estimate: 50KB per frame

            Log.Info("=== RECORDING STATISTICS ===");
            Log.Info($"Duration: {_recordingElapsedTime:F2} seconds");
            Log.Info($"Estimated frames: {totalFrames}");
            Log.Info($"Frame rate: {frameRate} fps");
            Log.Info($"Estimated file size: {estimatedFileSize / 1024 / 1024:F1} MB");
            Log.Info($"Output path: {_currentRecordingPath}");
            Log.Info("===========================");
        }
    }
}"}
